body { font-family: Tajawal, sans-serif; direction: rtl; background: #fff; }
.qr-box { padding: 28px; border: 2px dashed #003366; text-align: center; border-radius: 14px; background: #f0f5ff; max-width: 360px; margin: auto; }
.qr-icon { font-size: 40px; margin-bottom: 12px; }
.qr-box h4 { color: #003366; font-size: 18px; margin-bottom: 8px; }
.qr-box p { font-size: 13px; color: #556; margin-bottom: 16px; }
.qr-btn { background: #003366; color: #fff; border: none; padding: 10px 28px; border-radius: 20px; font-size: 13px; cursor: pointer; font-family: Tajawal, sans-serif; transition: background 0.3s; }
